// `prepare_wallpaper_video.EMBEDDED_METADATA_TRACKS`); `LivePhotoMov` clones and patches them per video.
import Foundation

struct MetadataTrackTemplate {
    let track: [UInt8]
    let sample: [UInt8]
    /// true: `com.apple.quicktime.live-photo-info` (one sample per video frame); false: `still-image-time` /
    /// `live-photo-still-image-transform` (a single sample).
    let isLivePhotoInfo: Bool
}

